sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_direction;
uniform float amzp_sortBy;
uniform float amzp_reverse;
uniform float amzp_lower;
uniform float amzp_upper;
uniform float amzp_invertRange;
uniform float amzp_maxLen;
uniform float amzp_sortWidth;
uniform float amzp_randomLen;
uniform float amzp_seed;
uniform float amzp_rate;
uniform float amzp_showMask;
uniform float amzp_amount;
uniform float amzp_overdrawOn;
uniform float amzp_quality;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float hs;
    float h1(float a, float b) { return fract(sin(a * 12.9898 + b * 78.233 + hs * 0.1371) * 43758.5453); }
    float4 px4(float2 px) {
        float2 uv = px / layer;
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return float4(0.0);
        return amzTexture(0, l2s(uv));
    }
    float key(float4 c) {
        float3 u = c.a > 0.0001 ? c.rgb / c.a : float3(0.0);
        if (int(amzp_sortBy) == 3) return u.r;
        if (int(amzp_sortBy) == 4) return u.g;
        if (int(amzp_sortBy) == 5) return u.b;
        float mx = max(u.r, max(u.g, u.b)), mn = min(u.r, min(u.g, u.b));
        if (int(amzp_sortBy) == 2) return mx > 1e-4 ? (mx - mn) / mx : 0.0;
        if (int(amzp_sortBy) == 1) {
            float d = mx - mn;
            if (d < 1e-4) return 0.0;
            float h;
            if (mx == u.r) h = mod((u.g - u.b) / d, 6.0);
            else if (mx == u.g) h = (u.b - u.r) / d + 2.0;
            else h = (u.r - u.g) / d + 4.0;
            return h / 6.0;
        }
        return dot(u, float3(0.2126, 0.7152, 0.0722));
    }
    bool inRange(float4 c) {
        if (c.a < 0.01) return false;
        float k = key(c);
        bool r = k >= min(amzp_lower, amzp_upper) && k <= max(amzp_lower, amzp_upper);
        return (amzp_invertRange>0.5) ? !r : r;
    }
    float2 org, dir;
    float c0, stp;
    float4 latt(float j) { return px4(org + dir * (c0 + (j + 0.5) * stp)); }
    float K[48];
    float4 C[48];
    float4 pickRank(float r, float n) {
        float lo = -0.001, hi = 1.001;
        for (int it = 0; it < 12; it++) {
            float mid = 0.5 * (lo + hi);
            float cnt = 0.0;
            for (int i = 0; i < 48; i++) {
                if (float(i) >= n) break;
                if (K[i] < mid) cnt += 1.0;
            }
            if (cnt > r) hi = mid; else lo = mid;
        }
        float best = 9.0;
        float4 col = float4(0.0);
        for (int i = 0; i < 48; i++) {
            if (float(i) >= n) break;
            float d = abs(K[i] - lo);
            if (d < best) { best = d; col = C[i]; }
        }
        return col;
    }
    void nmMain() {
        float2 W = layer;
        float2 p = amzLayerNorm() * W;
        float4 orig = px4(p);
        hs = amzp_seed + (amzp_rate > 0.0 ? floor(time * amzp_rate) * 7.31 : 0.0);
        float an = radians(-amzp_direction);
        dir = float2(cos(an), sin(an));
        float2 nrm = float2(-dir.y, dir.x);
        float2 cen = W * 0.5;
        float s = dot(p - cen, dir);
        float sw = max(amzp_sortWidth, 1.0);
        float row = (floor(dot(p - cen, nrm) / sw) + 0.5) * sw;
        org = cen + nrm * row;
        float L = max(amzp_maxLen, 4.0) * (1.0 - clamp(amzp_randomLen, 0.0, 1.0) * h1(row, 3.0));
        L = max(L, 4.0);
        float ph = h1(row, 7.0) * L;
        c0 = floor((s + ph) / L) * L - ph;
        float M = min(64.0, floor(L));
        stp = L / M;
        float j0 = clamp(floor((s - c0) / stp), 0.0, M - 1.0);
        if (!inRange(latt(j0))) {
            amzOutput = (amzp_showMask>0.5) ? float4(0.0, 0.0, 0.0, orig.a) : orig;
            return;
        }
        float a = j0, b = j0;
        for (int k = 0; k < 64; k++) {
            if (a < 0.5 || !inRange(latt(a - 1.0))) break;
            a -= 1.0;
        }
        for (int k = 0; k < 64; k++) {
            if (b > M - 1.5 || !inRange(latt(b + 1.0))) break;
            b += 1.0;
        }
        float len = b - a + 1.0;
        if ((amzp_showMask>0.5)) { amzOutput = float4(orig.a); return; }
        if (len < 1.5) { amzOutput = orig; return; }
        float Q = int(amzp_quality) == 0 ? 16.0 : (int(amzp_quality) == 2 ? 48.0 : 32.0);
        float n = min(Q, len);
        for (int i = 0; i < 48; i++) {
            if (float(i) >= n) break;
            float4 c = latt(a + (float(i) + 0.5) * len / n - 0.5);
            C[i] = c;
            K[i] = key(c);
        }
        float t = clamp((s - (c0 + a * stp)) / (len * stp), 0.0, 1.0);
        if ((amzp_reverse>0.5)) t = 1.0 - t;
        float rf = t * n - 0.5;
        float r0 = clamp(floor(rf), 0.0, n - 1.0);
        float r1 = min(r0 + 1.0, n - 1.0);
        float4 s0 = pickRank(r0, n);
        float4 s1 = pickRank(r1, n);
        float4 sorted = mix(s0, s1, clamp(rf - r0, 0.0, 1.0));
        float4 o = mix(orig, sorted, clamp(amzp_amount, 0.0, 1.0));
        amzOutput = float4(min(o.rgb, float3(o.a)), o.a);
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
